"""Write synthetic page splits to an on-disk YOLO-format detection dataset."""

from __future__ import annotations

from pathlib import Path

from acmp.eval.synthetic import SyntheticPage, boxes_to_yolo

_DATA_YAML = """\
# Auto-generated by acmp.eval.dataset — synthetic comic-panel detection dataset.
path: {root}
train: images/train
val: images/val
names:
  0: {class_name}
"""


def write_yolo_dataset(
    train: list[SyntheticPage],
    val: list[SyntheticPage],
    root: str | Path,
    class_name: str = "panel",
) -> Path:
    """Write train/val splits as a YOLO dataset and return the data.yaml path.

    Layout::

        root/
          images/{train,val}/*.png
          labels/{train,val}/*.txt   # one "0 cx cy w h" line per panel
          data.yaml
    """
    root = Path(root)
    for sub in ("images/train", "images/val", "labels/train", "labels/val"):
        (root / sub).mkdir(parents=True, exist_ok=True)

    def _dump(pages: list[SyntheticPage], split: str) -> None:
        for i, page in enumerate(pages):
            stem = f"{split}_{i:04d}"
            page.image.save(root / "images" / split / f"{stem}.png")
            lines = boxes_to_yolo(page.boxes, page.image.width, page.image.height)
            (root / "labels" / split / f"{stem}.txt").write_text("\n".join(lines) + "\n")

    _dump(train, "train")
    _dump(val, "val")

    data_yaml = root / "data.yaml"
    data_yaml.write_text(_DATA_YAML.format(root=root.resolve(), class_name=class_name))
    return data_yaml
